"use strict";(globalThis.webpackChunk_smallchat_docs=globalThis.webpackChunk_smallchat_docs||[]).push([[256],{7674(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docs":[{"type":"link","label":"Introduction","href":"/docs/intro","docId":"intro","unlisted":false},{"type":"link","label":"Getting Started","href":"/docs/getting-started","docId":"getting-started","unlisted":false},{"type":"link","label":"What it does","href":"/docs/what-it-does","docId":"what-it-does","unlisted":false},{"type":"link","label":"Why it matters","href":"/docs/why-it-matters","docId":"why-it-matters","unlisted":false},{"type":"category","label":"Deep Dive","items":[{"type":"link","label":"Overview","href":"/docs/concepts/","docId":"concepts/index","unlisted":false},{"type":"link","label":"Selector Table","href":"/docs/concepts/selector-table","docId":"concepts/selector-table","unlisted":false},{"type":"link","label":"Dispatch","href":"/docs/concepts/dispatch","docId":"concepts/dispatch","unlisted":false},{"type":"link","label":"ToolClass & ToolProxy","href":"/docs/concepts/tool-class","docId":"concepts/tool-class","unlisted":false},{"type":"link","label":"Resolution Cache","href":"/docs/concepts/resolution-cache","docId":"concepts/resolution-cache","unlisted":false},{"type":"link","label":"SCObject System","href":"/docs/concepts/sc-object","docId":"concepts/sc-object","unlisted":false},{"type":"link","label":"Function Overloading","href":"/docs/concepts/overloading","docId":"concepts/overloading","unlisted":false},{"type":"link","label":"Streaming","href":"/docs/concepts/streaming","docId":"concepts/streaming","unlisted":false},{"type":"link","label":"Method Swizzling","href":"/docs/concepts/swizzling","docId":"concepts/swizzling","unlisted":false},{"type":"link","label":"Truth Ledger","href":"/docs/concepts/truth-ledger","docId":"concepts/truth-ledger","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"CLI Reference","items":[{"type":"link","label":"Overview","href":"/docs/cli/","docId":"cli/index","unlisted":false},{"type":"link","label":"compile","href":"/docs/cli/compile","docId":"cli/compile","unlisted":false},{"type":"link","label":"inspect","href":"/docs/cli/inspect","docId":"cli/inspect","unlisted":false},{"type":"link","label":"resolve","href":"/docs/cli/resolve","docId":"cli/resolve","unlisted":false},{"type":"link","label":"explain","href":"/docs/cli/explain","docId":"cli/explain","unlisted":false},{"type":"link","label":"replay","href":"/docs/cli/replay","docId":"cli/replay","unlisted":false},{"type":"link","label":"serve","href":"/docs/cli/serve","docId":"cli/serve","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"API Reference","items":[{"type":"link","label":"ToolRuntime","href":"/docs/api/runtime","docId":"api/runtime","unlisted":false},{"type":"link","label":"Dispatch API","href":"/docs/api/dispatch","docId":"api/dispatch","unlisted":false},{"type":"link","label":"ToolCompiler","href":"/docs/api/compiler","docId":"api/compiler","unlisted":false},{"type":"link","label":"MCPServer","href":"/docs/api/mcp-server","docId":"api/mcp-server","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Manifests","items":[{"type":"link","label":"Manifest Format","href":"/docs/manifests/format","docId":"manifests/format","unlisted":false},{"type":"link","label":"Example Manifests","href":"/docs/manifests/examples","docId":"manifests/examples","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Integrations","items":[{"type":"link","label":"Overview","href":"/docs/integrations","docId":"integrations/index","unlisted":false},{"type":"link","label":"LoomMCP","href":"/docs/integrations/loom-mcp","docId":"integrations/loom-mcp","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","label":"Architecture","href":"/docs/architecture","docId":"architecture","unlisted":false}]},"docs":{"api/compiler":{"id":"api/compiler","title":"ToolCompiler","description":"ToolCompiler runs the Parse \u2192 Embed \u2192 Link pipeline over provider manifests, and buildArtifact() turns its result into a format 1.0 artifact: the file smallchat compile writes, pinned to the embedder that produced its vectors. The compiler never merges distinct tools. Two tools whose embeddings are at or above duplicateThreshold are a DuplicateToolError, unless allowDuplicates keeps both and reports the pair.","sidebar":"docs"},"api/dispatch":{"id":"api/dispatch","title":"Dispatch API","description":"The low-level dispatch functions behind ToolRuntime\'s methods. Each takes","sidebar":"docs"},"api/mcp-server":{"id":"api/mcp-server","title":"MCPServer","description":"MCPServer is what smallchat serve runs. It is an MCP aggregator built on the official SDK (@modelcontextprotocol/sdk): it serves a compiled toolkit\'s tools and forwards each tools/call, by exact name, to the upstream MCP server that owns the tool. It also serves tools and MCP Apps views you register programmatically. See serve for the behaviour a client sees.","sidebar":"docs"},"api/runtime":{"id":"api/runtime","title":"ToolRuntime","description":"ToolRuntime is the top-level class of @smallchat/core. It owns the","sidebar":"docs"},"architecture":{"id":"architecture","title":"Architecture","description":"\\"The big idea is messaging.\\" \u2014 Alan Kay","sidebar":"docs"},"cli/compile":{"id":"cli/compile","title":"compile","description":"Reads tool manifests from a source directory, generates semantic embeddings, groups tools into dispatch classes, and emits a compiled artifact.","sidebar":"docs"},"cli/explain":{"id":"cli/explain","title":"explain","description":"Shows why the runtime would (or would not) pick a tool for an intent. Nothing executes.","sidebar":"docs"},"cli/index":{"id":"cli/index","title":"CLI Reference","description":"The @smallchat/core package ships a CLI for compiling manifests, inspecting artifacts, testing dispatch resolution, and running the MCP server.","sidebar":"docs"},"cli/inspect":{"id":"cli/inspect","title":"inspect","description":"Inspects a compiled artifact and prints structured information about its contents.","sidebar":"docs"},"cli/replay":{"id":"cli/replay","title":"replay","description":"Checks golden dispatch traces against a compiled artifact: for each intent, the runtime must decide what the trace expects. Use it in CI so a changed description, embedder, threshold or policy cannot silently change which tool an intent selects.","sidebar":"docs"},"cli/resolve":{"id":"cli/resolve","title":"resolve","description":"Shows which tool the runtime would choose for a natural-language intent, and why. It runs the same resolution as runtime.resolve() and serve\'s smallchat_resolve: tiers, intent pins, the dispatch policy from the nearest smallchat.json, and verification. It prints the outcome, the candidate table and the proof digest. Nothing executes unless you pass --execute.","sidebar":"docs"},"cli/serve":{"id":"cli/serve","title":"serve","description":"Serves a compiled toolkit as one MCP server that forwards every tool call, by exact name, to the upstream MCP server that owns the tool. It is built on the official MCP SDK (@modelcontextprotocol/sdk) and speaks stdio by default, or Streamable HTTP with --http.","sidebar":"docs"},"concepts/dispatch":{"id":"concepts/dispatch","title":"Dispatch","description":"The dispatch layer turns a natural-language intent into at most one tool","sidebar":"docs"},"concepts/index":{"id":"concepts/index","title":"Deep Dive","description":"This section documents the internals of smallchat for engineers who want to understand or extend the runtime.","sidebar":"docs"},"concepts/overloading":{"id":"concepts/overloading","title":"Function Overloading","description":"A single ToolSelector can map to multiple implementations with different parameter signatures. The OverloadTable resolves which implementation to call based on argument types and arity \u2014 analogous to method overloading in statically-typed languages, but resolved at runtime.","sidebar":"docs"},"concepts/resolution-cache":{"id":"concepts/resolution-cache","title":"Resolution Cache","description":"The ResolutionCache is an LRU cache that stores resolved dispatches \u2014 analogous to the inline method cache in objc_msgSend. On a cache hit, dispatch skips the embedding and vector search entirely. On a cache miss, the full resolution runs and the result is stored for future calls.","sidebar":"docs"},"concepts/sc-object":{"id":"concepts/sc-object","title":"SCObject System","description":"The SCObject hierarchy is an NSObject-inspired base class for typed parameter passing. It enables runtime type checking, typed overload matching, and a consistent object model across dispatch boundaries.","sidebar":"docs"},"concepts/selector-table":{"id":"concepts/selector-table","title":"Selector Table","description":"The SelectorTable holds the compiled tool selectors \u2014 the dispatch keys","sidebar":"docs"},"concepts/streaming":{"id":"concepts/streaming","title":"Streaming","description":"Streaming is dispatch, one event at a time every token comes from the tool that runs.","sidebar":"docs"},"concepts/swizzling":{"id":"concepts/swizzling","title":"Method Swizzling","description":"Method swizzling replaces a tool implementation at runtime \u2014 analogous to","sidebar":"docs"},"concepts/tool-class":{"id":"concepts/tool-class","title":"ToolClass & ToolProxy","description":"ToolClass is the provider abstraction \u2014 analogous to a class in Objective-C. It groups related tools under a single dispatch table, can name a superclass whose selectors it inherits, and declares protocol conformance. loadRuntime() builds one class per provider from a compiled artifact; you build them yourself only to register tools in code.","sidebar":"docs"},"concepts/truth-ledger":{"id":"concepts/truth-ledger","title":"Truth Ledger","description":"Long-running agents accumulate \\"facts\\" with no record of who asserted them, what the evidence","sidebar":"docs"},"getting-started":{"id":"getting-started","title":"Getting Started","description":"Get from zero to a running dispatch in under five minutes.","sidebar":"docs"},"integrations/index":{"id":"integrations/index","title":"Integrations","description":"smallchat compiles any MCP-compatible toolset into a semantic dispatch table. These guides walk through wiring smallchat up to specific MCP servers and ecosystems.","sidebar":"docs"},"integrations/loom-mcp":{"id":"integrations/loom-mcp","title":"LoomMCP","description":"Pair smallchat semantic dispatch with LoomMCP exact-symbol retrieval.","sidebar":"docs"},"intro":{"id":"intro","title":"Introduction","description":"\\"The big idea is messaging.\\" \u2014 Alan Kay","sidebar":"docs"},"manifests/examples":{"id":"manifests/examples","title":"Example Manifests","description":"The examples/ directory in the smallchat repository contains ready-to-use manifests for common providers. Below are four representative examples.","sidebar":"docs"},"manifests/format":{"id":"manifests/format","title":"Manifest Format","description":"A provider manifest is a JSON file that describes a tool provider and its tools. Manifests are the input to the compile command and the ToolCompiler API.","sidebar":"docs"},"what-it-does":{"id":"what-it-does","title":"What it does","description":"smallchat is a message-passing tool compiler for LLM-powered applications. It solves one specific problem: given a natural-language intent from an LLM, choose at most one tool, and run it only when the dispatch policy allows. A call that runs nothing says why (isError, metadata.outcome).","sidebar":"docs"},"why-it-matters":{"id":"why-it-matters","title":"Why it matters","description":"The problem: tool proliferation","sidebar":"docs"}}}}')}}]);